SELECT , M.EVENT_CODE as eventCode, M.EVENT_TYPE as eventType, M.EVENT_NAME as eventName, M.PRIVACY_POLICY_YN as privacyPolicyYn, M.PRIVACY_POLICY_TTL as privacyPolicyTtl, M.PRIVACY_POLICY_DESC as privacyPolicyDesc, M.THIRD_PARTY_YN as thirdPartyYn, M.THIRD_PARTY_TTL as thirdPartyTtl, M.THIRD_PARTY_DESC as thirdPartyDesc, USR.CORP_NAME as corpName, EP.DEPARTMENT as department, EP.POSITION as position FROM SURVEY_USER U INNER JOIN SURVEY_MASTER M ON U.EVENT_SEQ = M.EVENT_SEQ LEFT JOIN USER USR ON M.USER_SEQ = USR.SEQ LEFT JOIN EVENT_PARTICIPANT EP ON U.SEQ = EP.SURVEY_USER_SEQ
ORDER BY U.REG_DATE DESC
LIMIT #{offset}, #{size}

SELECT U.SEQ as seq, USR.CORP_NAME as corpName, M.EVENT_NAME as eventName, M.EVENT_TYPE as eventType, U.USER_KEY as userKey, U.USER_NAME as userName, U.USER_PHONE as userPhone, U.RESEND_USER_PHONE as resendUserPhone, U.JUMIN_NUM as juminNum, U.ADDRESS as address, U.ADDRESS2 as address2, U.DEPOSIT_DATE as depositDate, U.SHIPMENT_DATE as shipmentDate, U.SURVEY_START_TIME as surveyStartTime, U.SUBMISSION_DATE as submissionDate, U.REG_DATE as regDate, EP.DEPARTMENT as department, EP.POSITION as position FROM SURVEY_USER U INNER JOIN SURVEY_MASTER M ON U.EVENT_SEQ = M.EVENT_SEQ LEFT JOIN USER USR ON M.USER_SEQ = USR.SEQ LEFT JOIN EVENT_PARTICIPANT EP ON U.SEQ = EP.SURVEY_USER_SEQ WHERE U.DEL_YN = 'N' AND U.SEQ IN
